import itertools

def get_semigroup(generators, limit):
    R = set()
    queue = list(generators)
    while queue:
        x = queue.pop(0)
        if x <= limit and x not in R:
            R.add(x)
            for g in generators:
                if x + g <= limit:
                    queue.append(x + g)
    return R

def solve():
    limit = 191
    min_removed = 95
    max_remaining_sum = 0

    # Try different starting a
    for a in range(1, 10):
        # For a given a, we want to find other generators to make |R| >= 95
        # and minimize the sum of R.
        # This is tricky. Let's try adding one more generator b.
        for b in range(a + 1, limit + 1):
            R = get_semigroup([a, b], limit)
            if len(R) >= min_removed:
                remaining_sum = sum(set(range(1, limit + 1)) - R)
                max_remaining_sum = max(max_remaining_sum, remaining_sum)

    return max_remaining_sum

print(solve())
